import{Et as e,Ot as t,n,qt as r}from"./chunks/framework.B_qehzBO.js";var i=JSON.parse(`{"title":"Peregrine — consola IA con Expo","description":"Una consola de chat con sensación nativa para iOS y Android — trae tu propio endpoint compatible con OpenAI, streaming SSE, claves en el Keychain y una matriz de cumplimiento de las leyes de diseño.","frontmatter":{"title":"Peregrine — consola IA con Expo","description":"Una consola de chat con sensación nativa para iOS y Android — trae tu propio endpoint compatible con OpenAI, streaming SSE, claves en el Keychain y una matriz de cumplimiento de las leyes de diseño."},"headers":[],"relativePath":"es/projects/peregrine/index.md","filePath":"es/projects/peregrine/index.md"}`),a={name:`es/projects/peregrine/index.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="peregrine-—-consola-ia-con-expo" tabindex="-1">Peregrine — consola IA con Expo <a class="header-anchor" href="#peregrine-—-consola-ia-con-expo" aria-label="Permalink to “Peregrine — consola IA con Expo”">​</a></h1><p><strong><a href="https://github.com/Godde3s/peregrine" target="_blank" rel="noreferrer">Peregrine</a></strong> es el capítulo móvil de mi historia de infraestructura de IA: una <strong>consola de chat con sensación nativa</strong> que habla con cualquier endpoint compatible con <code>/v1</code> de OpenAI — Ollama en tu propia máquina, una pasarela self-hosted como <a href="/Usf/es/projects/omnirouter/">OmniRouter</a>, o la nube. No existe un servidor de Peregrine: la clave vive en el Keychain y las conversaciones en MMKV, en el dispositivo.</p><h2 id="que-hace" tabindex="-1">Qué hace <a class="header-anchor" href="#que-hace" aria-label="Permalink to “Qué hace”">​</a></h2><ul><li>⚡ <strong>Chat en streaming</strong> — deltas SSE parseados con un generador asíncrono hecho a mano sobre <code>fetch</code>, abortable en pleno vuelo, con fallback sin streaming.</li><li>🔌 <strong>Trae tu propio endpoint</strong> — cualquier API que hable <code>/v1</code>; el onboarding valida el endpoint con una prueba de conexión real.</li><li>🧠 <strong>Explorador de modelos</strong> — <code>/v1/models</code> con TanStack Query: skeletons que igualan la forma final, errores inline, pull-to-refresh y barra de búsqueda nativa.</li><li>🔐 <strong>Seguridad sin cuentas</strong> — clave en el Keychain (<code>expo-secure-store</code>), transcripciones en MMKV, sin analytics ni telemetría.</li><li>🎨 <strong>Nativo por defecto</strong> — SF Symbols en iOS / Material en Android, Switch y Slider del sistema, haptics como puntuación, claro y oscuro desde el primer día.</li></ul><h2 id="el-stack" tabindex="-1">El stack <a class="header-anchor" href="#el-stack" aria-label="Permalink to “El stack”">​</a></h2><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Expo SDK 57 · React Native 0.86 · expo-router · TypeScript strict</span></span>
<span class="line"><span>Reanimated 4 (motion en el hilo de UI) · FlashList · TanStack Query</span></span>
<span class="line"><span>Zustand (dos stores estrechos) · MMKV · react-native-keyboard-controller</span></span></code></pre></div><p><strong>El estado es deliberadamente aburrido:</strong> estado de servidor en TanStack Query, estado de cliente en dos stores Zustand estrechos persistidos en MMKV, y estado efímero local a cada componente. El compositor es un input <strong>no controlado</strong> — cada tecla nunca re-renderiza la lista de conversaciones.</p><h2 id="construido-sobre-una-barra-de-diseno-no-sobre-gustos" tabindex="-1">Construido sobre una barra de diseño, no sobre gustos <a class="header-anchor" href="#construido-sobre-una-barra-de-diseno-no-sobre-gustos" aria-label="Permalink to “Construido sobre una barra de diseño, no sobre gustos”">​</a></h2><p>Las pantallas siguen el <a href="https://github.com/Appllama/appllama-skills" target="_blank" rel="noreferrer">appllama app-design skill</a>: semántica de navegación (push vs replace, modal vs sheet, puertas de un solo sentido con <code>Stack.Protected</code>), disciplina anti-slop (un acento, una familia de grises, una escala de radios declarada) y un presupuesto de motion que vive por completo en el hilo de UI. El repositorio incluye una <strong>matriz de cumplimiento ley por ley</strong> en <a href="https://github.com/Godde3s/peregrine/blob/main/docs/DESIGN.md" target="_blank" rel="noreferrer">docs/DESIGN.md</a>.</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> expo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> prebuild</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">     # dev build — MMKV necesita código nativo</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> expo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run:ios</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">      # o: npx expo run:android</span></span></code></pre></div><p>Licencia MIT.</p>`,11)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};